const input = $input.first().json;
const headers = input.headers || {};
const apiKey = headers['x-api-key'] || headers['authorization']?.replace('Bearer ', '');
if (!apiKey) return [{ json: { error: true, status: 401, message: 'Unauthorized' } }];
return [{ json: { api_key: apiKey, query: input.query || {} } }];

const input = $input.first().json;
const headers = input.headers || {};
const apiKey = headers['x-api-key'] || headers['authorization']?.replace('Bearer ', '');
if (!apiKey) return [{ json: { error: true, status: 401, message: 'Unauthorized' } }];
const query = input.query || {};
return [{ json: { api_key: apiKey, page: parseInt(query.page) || 1, limit: Math.min(parseInt(query.limit) || 50, 100), status: query.status || null, search: query.search || null } }];

